5.1.2 I/O端口的编程举例
void main( ) { //主函数
uchar i,temp;
while (1) {
temp=0x01; //左移初值赋给temp
for(i=0; i<8; i++) {
P1=~temp; // temp中的数据取反后送P1口
delay( ); // 延时
temp=temp<<1; // temp 中数据左移一位
}

