5.5.1 LCD 1602液晶显示模块简介
5．LCD1602基本操作
void check_busy(void) { //检查忙标志函数
uchar dt;
do {
dt=0xff; // dt为变量单元，初值为0xff 
E=0;
RS=0; //按照表5-4读写操作规定RS=0，E=1
//时才可读忙标志
RW=1;
E=1;
dt=out; // out为P0口，P0口的状态送入dt中
}while(dt&0x80); // 如果忙标志BF=1，继续循环检测，
//等待BF=0
E=0; // BF=0，LCD不忙，结束检测
}

5.5.1 LCD 1602液晶显示模块简介
5．LCD1602基本操作
void write_command(uchar com) { //写命令函数
check_busy();
E=0; //按规定RS和E同时为0时可以写入命令
RS=0; 
RW=0;
out=com; //将命令com写入P0口
E=1; //按规定写命令时，E应为正脉冲，即正
//跳变，所以前面先置E=0
_nop_( ); //空操作1个机器周期，等待硬件反应
E=0; // E由高电平变为低电平，LCD开始执行
//命令
delay(1); //延时，等待硬件响应
}

5.5.1 LCD 1602液晶显示模块简介
