void write_data(uchar dat) { //写数据函数
check_busy();
//检测忙标志BF=1则等待，若BF=0，则可对LCD操作
E=0; 
//按规定写数据时，E应为正脉冲，所以先置E=0
RS=1; //按规定RS=1和RW=0时可以写入数据
RW=0; 
out=dat; //将数据dat从P0口输出，即写入LC
E=1; //E产生正跳变
_nop_(); //空操作，给硬件反应时间
E=0; //E由高变低，写数据操作结束
delay(1);
}

