//重读P1.4～P1.7，若不全为1，定有键按下
code_h=0xfe; // P1.0行线置为0，开始行扫描
while((code_h&0x10)!=0x10); {
//判是否扫描到最后一行，若不是继续扫描
P1=code_h; //P1口输出行扫描值
if((P1&f0)!=0xf0); {
//如果P1.4～P1.7不全为1，该行有键按下

